"use strict";(self.webpackChunkdocs=self.webpackChunkdocs||[]).push([[3917],{56888:e=>{e.exports=JSON.parse('{"functions":[],"properties":[],"types":[],"name":"MurderEscape","desc":"The flagship game mode. One or two players are Murderers, one or two are\\nSheriffs, everyone else is Innocent.\\n\\n- Murderers get a knife after a grace period and must kill everyone.\\n- Sheriffs get a pistol and must kill the murderers.\\n- A Sheriff who kills an Innocent is executed and drops their pistol.\\n- A dropped pistol can only be picked up by an Innocent, who is then\\n  promoted to Sheriff.","source":{"line":16,"path":"src/Server/Features/Minigames/GameModes/MurderEscape.luau"}}')}}]);